import java.sql.*;
import java.util.*;

public class SecureCode {
    public static void main(String[] args) {
        // This code is secure because it uses PreparedStatement with parameterized queries.
        // The user input is treated as data, not executable SQL code, preventing SQL injection.
        String userInput = "SELECT * FROM users WHERE name = '" + userInput + "'";
        String query = "SELECT * FROM users WHERE name = ?";

        try (PreparedStatement stmt = conn.prepareStatement(query)) {
            // Use a parameter placeholder (?) instead of string concatenation
            stmt.setString(1, userInput);

            // Execute the query safely
            ResultSet rs = stmt.executeQuery();
            while (rs.next()) {
                System.out.println("Name: " + rs.getString("name"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

